def _sanitize_check_name(name: str) -> str:
    """Convert an arbitrary string into a valid Dagster check name.

    Replaces all characters that are not alphanumeric or underscore with ``_``, truncates the
    result to 100 characters, strips leading/trailing underscores, and returns ``"check"`` if the
    result would otherwise be empty.
    """
    sanitized = re.sub(r"[^0-9a-zA-Z_]", "_", name)
    sanitized = sanitized[:100]
    sanitized = sanitized.strip("_")
    return sanitized or "check"


def _parse_check_identifiers_from_yaml(yaml_path: Path, dataset: str) -> list[str]:
    """Read a SodaCL YAML file and return sanitized check identifiers for the given dataset.

    Looks for the ``checks for {dataset}`` key. Plain string list items are sanitized via
    :func:`_sanitize_check_name`. Dict items whose config contains a ``name`` key use that name
    value directly. Returns ``[]`` if the dataset key is not found or the file is empty.
    """
    if not yaml_path.exists():
        return []

    with open(yaml_path) as f:
        data = yaml.safe_load(f)

    if not data:
        return []

    checks = data.get(f"checks for {dataset}")
    if not checks:
        return []

    identifiers: list[str] = []
    for item in checks:
        if isinstance(item, str):
            identifiers.append(_sanitize_check_name(item))
        elif isinstance(item, dict):
            for check_expr, config in item.items():
                if isinstance(config, dict) and "name" in config:
                    identifiers.append(str(config["name"]))
                else:
                    identifiers.append(_sanitize_check_name(str(check_expr)))
    return identifiers


def _collect_check_identifiers_for_dataset(
    checks_paths: list[str], project_root: Path, dataset: str
) -> list[str]:
    """Aggregate sanitized check identifiers from all provided YAML files for the given dataset.

    Relative paths are resolved against ``project_root``.
    """
    identifiers: list[str] = []
    for path in checks_paths:
        yaml_path = Path(path)
        if not yaml_path.is_absolute():
            yaml_path = project_root / yaml_path
        identifiers.extend(_parse_check_identifiers_from_yaml(yaml_path, dataset))
    return identifiers


def _get_outcome(soda_check: Any) -> str:
    """Extract the outcome from a Soda check result object.

    Tries the ``outcome`` attribute first, then ``result``, then returns ``"unknown"``.
    """
    outcome = getattr(soda_check, "outcome", None)
    if outcome is not None:
        return str(outcome)
    result = getattr(soda_check, "result", None)
    if result is not None:
        return str(result)
    return "unknown"


def _get_check_name(soda_check: Any) -> str:
    """Extract the check name from a Soda check result object.

    Tries the ``name`` attribute first, then falls back to ``check_name``.
    """
    name = getattr(soda_check, "name", None)
    if name is not None:
        return str(name)
    return str(getattr(soda_check, "check_name", None))


def _get_severity(soda_check: Any, default_severity: str = "warn") -> str:
    """Extract the severity from a Soda check result object.

    Returns ``soda_check.severity`` if present, otherwise the ``default_severity`` parameter.
    """
    severity = getattr(soda_check, "severity", None)
    if severity is not None:
        return str(severity)
    return default_severity


def _to_dagster_severity(severity: str) -> dg.AssetCheckSeverity:
    """Convert a Soda severity string to a Dagster ``AssetCheckSeverity``.

    ``"error"`` or ``"fail"`` maps to ``ERROR``; ``"warn"``, ``"pass"``, or any other value maps
    to ``WARN``.
    """
    if severity in ("error", "fail"):
        return dg.AssetCheckSeverity.ERROR
    return dg.AssetCheckSeverity.WARN


def _filter_results_for_dataset(scan_results: Any, dataset: str) -> list[Any]:
    """Filter Soda scan results to only those matching the given dataset.

    For each check result, the ``table`` attribute is consulted first, then ``table_name`` if
    ``table`` is absent.
    """
    checks = getattr(scan_results, "checks", None) or []
    matching: list[Any] = []
    for soda_check in checks:
        table = getattr(soda_check, "table", None)
        if table is None:
            table = getattr(soda_check, "table_name", None)
        if table == dataset:
            matching.append(soda_check)
    return matching


